query:
SELECT transaction_timestamp() AS captured_at,p.oid::regprocedure::text AS signature,p.proname,pg_get_functiondef(p.oid) AS definition,md5(p.prosrc) AS source_md5,md5(pg_get_functiondef(p.oid)) AS definition_md5,pg_get_userbyid(p.proowner) AS owner,p.proconfig,
(SELECT jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege_type',a.privilege_type,'is_grantable',a.is_grantable) ORDER BY a.grantee::regrole::text,a.privilege_type) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))a) AS grants
FROM pg_proc p WHERE p.oid IN ('public.fn_freeroll_fill_targets(uuid)'::regprocedure,'public.fn_overlay_at_risk(uuid)'::regprocedure,'public.fn_tournament_progress_metrics(integer,integer)'::regprocedure) ORDER BY p.proname;
